import{Q as e,X as t,ft as n,n as r}from"./chunks/framework.CXbMDk3A.js";var i=JSON.parse(`{"title":"A Vision for Recon","description":"","frontmatter":{"title":"A Vision for Recon","updated":"2026-10-27T00:00:00.000Z"},"headers":[],"relativePath":"VISION.md","filePath":"VISION.md"}`),a={name:`VISION.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="a-vision-for-recon" tabindex="-1">A Vision for Recon <a class="header-anchor" href="#a-vision-for-recon" aria-label="Permalink to “A Vision for Recon”">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2><p>Recon is an agent-facing reverse-engineering workbench for researchers and developers who need to understand software from the evidence available to them. Its scope includes binaries and recovered code, running object and view hierarchies, web documents and styles, network activity, packaged resources, and public or private platform APIs. Investigation can answer a focused question about an application&#39;s implementation, appearance, data, or behavior without requiring a recreation project.</p><p>Controlled experiments, behavioral specifications, and comparison with independent implementations remain important workflows within that scope. A useful answer says what was inspected or tried, what was found, and which evidence supports the claim, so another person or agent can challenge it. macOS is the first host; applications running on that host, in simulators, and on connected devices are distinct investigation targets.</p><h2 id="current-capabilities" tabindex="-1">Current capabilities <a class="header-anchor" href="#current-capabilities" aria-label="Permalink to “Current capabilities”">​</a></h2><p>Recon currently lists discovered and running macOS application bundles, inspects one bundle&#39;s metadata and running process IDs without activating it, and explicitly launches the selected bundle through its Rust CLI. It also observes a running macOS application without activating it, changing focus, or sending input: lists its windows, reads the accessibility tree of the application or of one window, including reachable windows on other Spaces, and captures one window to a PNG file. Those observations use Screen Recording and Accessibility permissions that belong to the locally signed <code>recon</code> executable rather than to the program that launched it.</p><p>Recon can also establish an explicit, process-bound native inspection session and read a macOS application&#39;s AppKit windows, views, cells, layers, layout, and observed fonts. Native queries under <code>ui view</code>, accessibility queries under <code>ui ax</code>, shared WindowServer capture, and native/AX correlation preserve their separate evidence sources and identities. The current native scope is Apple silicon on macOS 27; cooperative and explicitly prepared research access have different prerequisites. Catalyst, UIKit, Simulator, and connected-device inspection remain future work.</p><p>The current <code>ui tree</code> spelling is retired. Accessibility trees use <code>recon ui ax tree</code>; native hierarchies use <code>recon ui view</code> with an explicit session. Binary analysis, other runtime inspection, web and Electron inspection, live network capture, asset extraction, private-API discovery, UI interaction, experiments, behavioral specifications, verification, and persistent evidence remain future work.</p><p>Agents can learn the CLI through built-in help, inspect each command&#39;s schema, constraints, and effects, and classify compact JSON errors by stable code. Build-version and execution-context reports identify the running binary; on macOS, context checks its own signing identity and permission state without requesting grants.</p><p>Agents can list only running bundles and limit accessibility-tree depth. Application trees can also exclude the main menu bar without dropping status menus; unqualified trees still include menus. Tree nodes use one sparse encoding, and results distinguish requested narrowing from incomplete reads.</p><h2 id="capability-map" tabindex="-1">Capability map <a class="header-anchor" href="#capability-map" aria-label="Permalink to “Capability map”">​</a></h2><p>This map records the intended scope and its GitHub tracking. Only the current capabilities above are implemented. Open issues are capability briefs, not approved specifications, settled command syntax, or permission to change a target&#39;s security settings. Historical proposals retain the narrower intent under which their features shipped.</p><table tabindex="0"><thead><tr><th>Capability</th><th>Intended investigation</th><th>Tracking</th></tr></thead><tbody><tr><td>macOS applications and accessibility</td><td>Discover/inspect/launch apps; observe windows, AX trees, and screenshots. Implemented.</td><td><a href="https://github.com/markmals/recon/issues/20" target="_blank" rel="noreferrer">#20</a>, <a href="https://github.com/markmals/recon/issues/15" target="_blank" rel="noreferrer">#15</a>, proposals 0001 through 0004</td></tr><tr><td>Native binaries and managed code</td><td>Mach-O metadata, disassembly, decompilation, references, and .NET metadata/CIL.</td><td><a href="https://github.com/markmals/recon/issues/2" target="_blank" rel="noreferrer">#2</a>, <a href="https://github.com/markmals/recon/issues/7" target="_blank" rel="noreferrer">#7</a></td></tr><tr><td>Web and Electron</td><td>Live DOM hierarchy, CSSOM rules and cascade, computed styles/layout, scripts, modules, IPC, and network observations.</td><td><a href="https://github.com/markmals/recon/issues/4" target="_blank" rel="noreferrer">#4</a>, <a href="https://github.com/markmals/recon/issues/5" target="_blank" rel="noreferrer">#5</a></td></tr><tr><td>Native UI structure</td><td>Actual AppKit view/cell/layer hierarchies, fonts, constraints, materials, and SwiftUI backing boundaries; UIKit/Mac Catalyst hierarchy and UIKit screenshots/logs in Simulator/device investigations.</td><td><a href="https://github.com/markmals/recon/issues/44" target="_blank" rel="noreferrer">#44</a>, <a href="https://github.com/markmals/recon/issues/55" target="_blank" rel="noreferrer">#55</a>, <a href="https://github.com/markmals/recon/issues/40" target="_blank" rel="noreferrer">#40</a>, <a href="https://github.com/markmals/recon/issues/41" target="_blank" rel="noreferrer">#41</a></td></tr><tr><td>Native inspection access</td><td>Establish supported, process-scoped headless sessions for macOS, UIKit Simulator, and UIKit physical-device inspectors, with explicit prerequisites and lifecycle. Mac Catalyst compatibility is verified by its inspector on the macOS session foundation.</td><td><a href="https://github.com/markmals/recon/issues/51" target="_blank" rel="noreferrer">#51</a>, <a href="https://github.com/markmals/recon/issues/52" target="_blank" rel="noreferrer">#52</a>, <a href="https://github.com/markmals/recon/issues/53" target="_blank" rel="noreferrer">#53</a>, <a href="https://github.com/markmals/recon/issues/55" target="_blank" rel="noreferrer">#55</a></td></tr><tr><td>Runtime objects and interventions</td><td>Loaded classes, methods, properties, ivars, live objects/heap references; separately requested state changes and method calls.</td><td><a href="https://github.com/markmals/recon/issues/45" target="_blank" rel="noreferrer">#45</a>, <a href="https://github.com/markmals/recon/issues/49" target="_blank" rel="noreferrer">#49</a></td></tr><tr><td>In-process network activity</td><td>FLEX-style request/response and message history inside UIKit apps in the Simulator or on connected devices, and inside AppKit apps.</td><td><a href="https://github.com/markmals/recon/issues/42" target="_blank" rel="noreferrer">#42</a>, <a href="https://github.com/markmals/recon/issues/43" target="_blank" rel="noreferrer">#43</a>, <a href="https://github.com/markmals/recon/issues/48" target="_blank" rel="noreferrer">#48</a></td></tr><tr><td>Saved network evidence</td><td>HAR/SAZ requests and exposed bodies; packet fields, filters, and summaries. These are distinct from in-process acquisition.</td><td><a href="https://github.com/markmals/recon/issues/6" target="_blank" rel="noreferrer">#6</a>, <a href="https://github.com/markmals/recon/issues/11" target="_blank" rel="noreferrer">#11</a>, <a href="https://github.com/markmals/recon/issues/12" target="_blank" rel="noreferrer">#12</a></td></tr><tr><td>Packages, images, and icons</td><td>Inventory/extract bundle resources and supported asset-catalog variants; inspect/export accessible runtime images with their different provenance.</td><td><a href="https://github.com/markmals/recon/issues/13" target="_blank" rel="noreferrer">#13</a></td></tr><tr><td>Platform APIs and SDK knowledge</td><td>Discover installed private-framework declarations and shared-cache metadata; separately query public SDK symbols/availability and source-attributed framework patterns.</td><td><a href="https://github.com/markmals/recon/issues/46" target="_blank" rel="noreferrer">#46</a>, <a href="https://github.com/markmals/recon/issues/47" target="_blank" rel="noreferrer">#47</a></td></tr><tr><td>Application-local state</td><td>Bundle/container files, live and persisted preferences, SQLite evidence, and app logs, with explicit source/access boundaries.</td><td><a href="https://github.com/markmals/recon/issues/3" target="_blank" rel="noreferrer">#3</a>, <a href="https://github.com/markmals/recon/issues/50" target="_blank" rel="noreferrer">#50</a></td></tr><tr><td>Process behavior</td><td>PTY interaction, terminal output, exit behavior, filesystem effects, and run comparisons.</td><td><a href="https://github.com/markmals/recon/issues/14" target="_blank" rel="noreferrer">#14</a></td></tr><tr><td>Platform control</td><td>Explicit macOS UI input; Simulator lifecycle, settings, data, and input; supported physical-device/app operations.</td><td><a href="https://github.com/markmals/recon/issues/24" target="_blank" rel="noreferrer">#24</a>, <a href="https://github.com/markmals/recon/issues/38" target="_blank" rel="noreferrer">#38</a>, <a href="https://github.com/markmals/recon/issues/39" target="_blank" rel="noreferrer">#39</a></td></tr><tr><td>Windows</td><td>Application investigation, UI observation, and explicit input under Windows-specific contracts.</td><td><a href="https://github.com/markmals/recon/issues/21" target="_blank" rel="noreferrer">#21</a>, <a href="https://github.com/markmals/recon/issues/16" target="_blank" rel="noreferrer">#16</a>, <a href="https://github.com/markmals/recon/issues/25" target="_blank" rel="noreferrer">#25</a></td></tr><tr><td>Android</td><td>Device/emulator investigation, APK code, and decoded resources.</td><td><a href="https://github.com/markmals/recon/issues/9" target="_blank" rel="noreferrer">#9</a>, <a href="https://github.com/markmals/recon/issues/8" target="_blank" rel="noreferrer">#8</a>, <a href="https://github.com/markmals/recon/issues/10" target="_blank" rel="noreferrer">#10</a></td></tr><tr><td>Investigation workflows</td><td>Bounded discovery, experiments, behavioral specification/comparison, and durable evidence across sessions.</td><td><a href="https://github.com/markmals/recon/issues/17" target="_blank" rel="noreferrer">#17</a>, <a href="https://github.com/markmals/recon/issues/18" target="_blank" rel="noreferrer">#18</a>, <a href="https://github.com/markmals/recon/issues/19" target="_blank" rel="noreferrer">#19</a>, <a href="https://github.com/markmals/recon/issues/23" target="_blank" rel="noreferrer">#23</a></td></tr></tbody></table><p>In-process network inspection observes the application APIs that are instrumented, including request/response bodies those APIs expose for HTTPS. It is different from capturing encrypted packets on a host or device interface. Neither technique establishes complete coverage of every networking stack, process, or time interval. Likewise, exporting a runtime image does not recover every original resource or every compiled asset-catalog variant.</p><p>GitHub&#39;s blocking relationships record completion prerequisites; other issue cross-references can describe related capabilities or integration points without imposing whole-feature sequencing. The session issues isolate access already required by individual native inspectors. Static portions of mixed static/live issues can proceed before live-access prerequisites finish. UIKit briefs that do not yet select Simulator or physical-device support must record that choice and its session prerequisite when their proposals define supported targets.</p><h2 id="prior-art-and-intended-lineage" tabindex="-1">Prior art and intended lineage <a class="header-anchor" href="#prior-art-and-intended-lineage" aria-label="Permalink to “Prior art and intended lineage”">​</a></h2><p><a href="https://github.com/markmals/apple-platform-tools/tree/3e587d4f0f7a5c771234fdf52ac409b6d58a65ff" target="_blank" rel="noreferrer">apple-platform-tools</a> supplies source-backed precedents for native AppKit/runtime inspection, Mach-O reads, private-framework header extraction, public SDK symbol queries, and curated framework-pattern search. Its <code>redump</code> disassembler work stops at backend detection, and some advertised heap/pointer-safety machinery is unfinished. SDK declarations, static framework metadata, and classes loaded in a live target answer different questions. Source inspection establishes these implementation boundaries; this alignment pass did not run or validate those tools.</p><p><a href="https://github.com/markmals/flexscope/tree/144d50b82462e1a328123794a21ddcce8d92e811" target="_blank" rel="noreferrer">flexscope&#39;s checked-in plan</a> is specification-only and concentrates on AppKit view/runtime inspection. The owner&#39;s clarification on 2026-10-27 establishes the broader intended lineage: Flexscope was to expose functionality from <a href="https://github.com/FLEXTool/FLEX/tree/dac6130e0c7aca0bbf7ff8c0b57ba284776bfdff" target="_blank" rel="noreferrer">FLEX</a>, initially through a more composable upstream library, then by rebuilding the needed functionality after the maintainer declined that direction. The checked-in Flexscope scope does not bound that intended work.</p><p><a href="https://github.com/FLEXTool/FLEX/pull/740" target="_blank" rel="noreferrer">FLEX PR #740</a>, authored by the owner, proposed a separate headless AppKit walker and is closed without merging. It explicitly excluded the core-engine split. The maintainer discussion above is owner-provided history; the public PR does not contain that discussion. Recon&#39;s direction does not depend on reviving the PR or persuading FLEX to become a composable library.</p><p>FLEX itself provides concrete UIKit prior art beyond the walker: <a href="https://github.com/FLEXTool/FLEX/blob/dac6130e0c7aca0bbf7ff8c0b57ba284776bfdff/Classes/Network/PonyDebugger/FLEXNetworkObserver.m" target="_blank" rel="noreferrer">in-process network observation</a>, transaction/body recording, object/heap exploration, runtime editing and method calls, defaults, database and log inspection, <a href="https://github.com/FLEXTool/FLEX/blob/dac6130e0c7aca0bbf7ff8c0b57ba284776bfdff/Classes/GlobalStateExplorers/FileBrowser/FLEXFileBrowserController.m" target="_blank" rel="noreferrer">bundle/container browsing and file sharing</a>, and <a href="https://github.com/FLEXTool/FLEX/blob/dac6130e0c7aca0bbf7ff8c0b57ba284776bfdff/Classes/ObjectExplorers/Sections/Shortcuts/FLEXImageShortcuts.m" target="_blank" rel="noreferrer">runtime image inspection/export</a>. These inform native, headless Recon capabilities for UIKit and AppKit. They establish partial resource-extraction precedent, not a complete compiled-asset extractor or an existing AppKit port. Reuse must respect the relevant source licenses, including <a href="https://github.com/FLEXTool/FLEX/blob/dac6130e0c7aca0bbf7ff8c0b57ba284776bfdff/LICENSE" target="_blank" rel="noreferrer">FLEX&#39;s distribution restrictions</a>.</p><p>Embedding inspection code in a cooperative app, attaching to a running app, and accessing a protected third-party or system app have different prerequisites. FLEX running inside an iOS app does not establish arbitrary-device injection; Flexscope&#39;s dedicated research-machine assumptions do not authorize changes to Recon users&#39; machines. Each feature proposal must ground its supported targets, effects, and verification independently.</p><h2 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to “Goals”">​</a></h2><ul><li>Make feature discovery systematic: find candidate behaviors, distinguish observations from hypotheses, and keep unanswered questions visible.</li><li>Inspect software structure and implementation directly: code, native objects and views, DOM/CSSOM, protocols, files, assets, and platform APIs are all valid subjects of reverse engineering.</li><li>Make focused inspection useful on its own, with machine-readable results and provenance that can later participate in a larger investigation.</li><li>Make controlled experiments repeatable enough to isolate the effect of an input, environment change, or action sequence on the reference application&#39;s behavior.</li><li>Turn observed behavior into precise specifications that can be tested against an independent implementation.</li><li>Make differential verification explain agreements and disagreements with the reference, including the evidence behind each conclusion.</li><li>Preserve observations, artifacts, conditions, and provenance across agent sessions so findings can be revisited rather than rediscovered.</li></ul><h2 id="minimum-viable-product" tabindex="-1">Minimum viable product <a class="header-anchor" href="#minimum-viable-product" aria-label="Permalink to “Minimum viable product”">​</a></h2><p>The existing minimum viable product milestone completes a bounded behavioral investigation of reference applications running on macOS through the Rust CLI: native macOS applications, Electron applications, and web applications in a browser. An agent can enumerate an application, discover multiple feature entry points and contextual prerequisites, resume its session with evidence intact, run a parameterized JSONC experiment, and turn the observations into a behavioral specification. It can execute equivalent behavior against a reference and an independent implementation, reporting matches, meaningful discrepancies, and inconclusive comparisons. SQLite stores structured records and content-addressed storage keeps larger artifacts; every claim remains traceable to observations, conditions, application versions, and the experiment that supports it.</p><p>The minimum proves the behavioral investigation loop on purpose-built macOS fixtures for native, Electron, and web applications. It is one bounded milestone within the broader reverse-engineering vision, not the definition of every useful Recon capability. Specialized inspections can deliver value before that loop is complete. Adapters and analysis providers must report unavailable capabilities and permission failures explicitly. iOS Simulator, connected iOS devices, Windows, Android, and other target environments require their own proposals and are outside this existing minimum; running their tools from a Mac does not make them macOS applications.</p><h2 id="design-principles" tabindex="-1">Design principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to “Design principles”">​</a></h2><ul><li><strong>Evidence before confidence.</strong> Keep raw observations, conditions, and interpretations distinguishable; a behavioral claim must point back to the experiment that supports it.</li><li><strong>Control before coverage.</strong> Prefer a small experiment with a clear baseline and variation over broad but ambiguous capture. When they conflict, reproducibility takes precedence over the number of explored features.</li><li><strong>Agents can inspect the whole trail.</strong> Favor a Rust CLI and structured, durable experiment and result records that an agent can read, write, and revisit without relying on transient chat history. Human readers need the same trail to be legible.</li><li><strong>Capabilities determine integration boundaries.</strong> Recon owns a coherent CLI, targeting, capability discovery, and evidence contracts. It can implement native inspection capabilities and use external providers where they fit. REA remains a candidate analysis provider, especially for binary and artifact workflows; it is neither a prerequisite for every inspection nor the definition of Recon&#39;s scope. Disassembler integration should reuse mature engines rather than require Recon to build a new decompiler.</li><li><strong>Different evidence stays distinguishable.</strong> An accessibility node, a native view object, a DOM node, and a CSS rule describe different aspects of an interface. SDK declarations, metadata extracted from a binary, and APIs observed in a running process likewise establish different facts. Correlate them without presenting one as another.</li><li><strong>Inspection effects are explicit.</strong> Reading files, querying another process, loading a framework, attaching a debugger, injecting code, intercepting traffic, and changing a target have different prerequisites and effects. Report those boundaries; a research tool&#39;s prior authorization to weaken security does not transfer to Recon.</li><li><strong>Uncertainty stays explicit.</strong> A mismatch is a finding to investigate, not proof that either the reference or independent implementation is wrong. Report missing evidence and environmental differences rather than manufacture agreement.</li></ul><h2 id="beyond-the-minimum" tabindex="-1">Beyond the minimum <a class="header-anchor" href="#beyond-the-minimum" aria-label="Permalink to “Beyond the minimum”">​</a></h2><ul><li>Investigation of iOS apps in the Simulator and on connected physical devices, including UIKit hierarchy/runtime inspection, application data/resources, and in-process network activity. Device management and simulator lifecycle are separate capabilities with different access constraints.</li><li>Investigation on Windows, Android, and other platforms. Each target environment needs its own grounding of installation, running instances, observation, and control.</li><li>Broader discovery across complex third-party applications and reusable experiments spanning multiple application families, once the macOS fixture loop is reliable.</li><li>Native, headless capabilities informed by apple-platform-tools, Flexscope&#39;s intended FLEX-derived functionality, and FLEX itself, alongside integrations with REA, re-cli, or winctl/winctl-win where suitable. Prior art informs capabilities; its command layout, GUI, dependencies, security posture, and unfinished promises are not inherited requirements.</li><li>Authenticated remote hosts and optional MCP integration, after local CLI investigations can be reproduced reliably.</li></ul><h2 id="non-goals" tabindex="-1">Non-goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to “Non-goals”">​</a></h2><ul><li>An autonomous coding agent or application generator. Recon supplies evidence and tools to an external agent rather than choosing and implementing a recreation on its behalf.</li><li>A guarantee of recovering original source code or producing a faithful clone. Disassembly, decompilation, metadata extraction, and direct implementation inspection are in scope; their outputs must retain uncertainty and must not be presented as the original source.</li><li>Exhaustive, unattended exploration of every application. The initial value comes from a traceable investigation of a bounded behavior, where an agent or researcher can choose and revise the question.</li><li>Treating one observation or a passing comparison as a universal specification. Platform, version, state, and experimental conditions limit what the evidence establishes.</li><li>Unconditional access to every target or automatic weakening of host or device protections. Unsupported attachment, unavailable inspection interfaces, and encrypted or inaccessible evidence must be reported honestly.</li></ul><h2 id="revision-history" tabindex="-1">Revision history <a class="header-anchor" href="#revision-history" aria-label="Permalink to “Revision history”">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>Change</th><th>Related proposal</th></tr></thead><tbody><tr><td>2026-10-14</td><td>Created the initial project vision.</td><td>N/A</td></tr><tr><td>2026-10-15</td><td>Added macOS application investigation through the Rust CLI.</td><td>proposal.0001</td></tr><tr><td>2026-10-15</td><td>Limited the minimum viable product to macOS, including Electron and web applications; moved Windows and Android beyond it.</td><td>N/A</td></tr><tr><td>2026-10-15</td><td>Added macOS UI observation of windows, accessibility trees, and window screenshots.</td><td>proposal.0002</td></tr><tr><td>2026-10-27</td><td>Added runtime command discovery, typed JSON errors, build provenance, and preflight-only execution-context reporting.</td><td>proposal.0003</td></tr><tr><td>2026-10-27</td><td>Added running-only application listing, depth and main-menu narrowing, and sparse tree output with explicit completeness markers.</td><td>proposal.0004</td></tr><tr><td>2026-10-27</td><td>Clarified reverse engineering across code, runtime/UI structure, web styles, network activity, resources, and platform APIs; retained behavioral verification as one workflow and distinguished the existing macOS minimum from the broader scope.</td><td>Owner clarification; no feature implementation approval</td></tr><tr><td>2026-10-27</td><td>Recorded FLEX-derived UIKit/AppKit network, resource, runtime, and application-state scope; distinguished the owner&#39;s intended reimplementation from the unbuilt Flexscope checkout and closed AppKit-walker PR #740; linked capability families to GitHub issues.</td><td>Owner clarification; no feature implementation approval</td></tr><tr><td>2026-10-29</td><td>Added process-bound native AppKit inspection sessions, native view/cell/layer/layout/font queries, the <code>ui ax</code> migration, and native/AX correlation with shared no-focus behavior.</td><td>proposal.0005</td></tr></tbody></table>`,34)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};